/// <summary>
/// CB731_LaserNetBundleTOMultithreadBatch.
/// Data contract class for the order shipment bundling reporting job.
/// </summary>
[DataContract]
class METOrderShipmentBundlingReportingJobContract extends METSysOperationTaskDataContract
{
    guid topPickingProcessId;
    str printDestSettingsSerialized;
    str packedQuery;

}

Method.Source:
    /// <summary>
/// get/set the top picking process guid id
/// </summary>
/// <param name = "_topPickingProcessId">Top picking process guid id</param>
/// <returns>Top picking process guid id</returns>
[DataMember, SysOperationControlVisibilityAttribute(false)]
public guid parmTopPickingProcessId(guid _topPickingProcessId = topPickingProcessId)
{
    topPickingProcessId = _topPickingProcessId;

    return topPickingProcessId;
}

/// <summary>
/// Gets/sets serialized <c>SRSPrintDestinationSettings</c>.
/// </summary>
/// <param name = "_printDestSettingsSerialized">
/// Serialized object.
/// </param>
/// <returns>
/// Serialized object.
/// </returns>
[DataMember, SysOperationControlVisibilityAttribute(false)]
public str parmPrintDestSettingsSerialized(str _printDestSettingsSerialized = printDestSettingsSerialized)
{
    printDestSettingsSerialized = _printDestSettingsSerialized;
    return printDestSettingsSerialized;
}

[DataMemberAttribute,
 AifQueryTypeAttribute('_packedQuery', queryStr(METOrderShipmentBundlingReportingJobQuery))]
public str parmPackedQuery(str _packedQuery = packedQuery)
{
    packedQuery = _packedQuery;
    return packedQuery;
}

/// <summary>
/// Gets query.
/// </summary>
/// <returns>
/// Query.
/// </returns>
public Query getQuery()
{
    return new Query(SysOperationHelper::base64Decode(packedQuery));
}

/// <summary>
/// Sets query.
/// </summary>
/// <param name = "_query">
/// Query.
/// </param>
public void setQuery(Query _query)
{
    packedQuery = SysOperationHelper::base64Encode(_query.pack());
}

/// <summary>
/// Initializes query.
/// </summary>
/// <param name = "_transactionType">Transaction type.</param>
public void initQuery(METOrderTransactionType _transactionType)
{
    Query query;
    QueryBuilddataSource qbds;

    query = this.getQuery();
    qbds = query.dataSourceTable(tableNum(METSalesOrderShipmentLoadHeader));

    if (qbds)
    {
        SysQuery::findOrCreateRange(qbds, fieldNum(METSalesOrderShipmentLoadHeader, LoadId));
        SysQuery::findOrCreateRange(qbds, fieldNum(METSalesOrderShipmentLoadHeader, ShipmentId));
        SysQuery::findOrCreateRange(qbds, fieldNum(METSalesOrderShipmentLoadHeader, Route));
        SysQuery::findOrCreateRange(qbds, fieldNum(METSalesOrderShipmentLoadHeader, RouteStopNum));
        SysQuery::findOrCreateRange(qbds, fieldNum(METSalesOrderShipmentLoadHeader, SentToLaserNet)).value(enum2Str(NoYes::No));
        SysQuery::findOrCreateRange(qbds, fieldNum(METSalesOrderShipmentLoadHeader, LoadStatus)).value(enum2Str(MetShipmentStatus::Shipped));

        var qbrTransactionType = SysQuery::findOrCreateRange(qbds, fieldNum(METSalesOrderShipmentLoadHeader, TransactionType));
        qbrTransactionType.value(enum2Str(_transactionType));
        qbrTransactionType.status(RangeStatus::Locked);

        var qbrWarehouse = SysQuery::findOrCreateRange(qbds, fieldNum(METSalesOrderShipmentLoadHeader, Warehouse));

        if (_transactionType == METOrderTransactionType::TransferOrder)
        {
            qbrWarehouse.label("@SYS25253");
            SysQuery::findOrCreateRange(qbds, fieldNum(METSalesOrderShipmentLoadHeader, ToWarehouse));
        }

    }

    this.setQuery(query);

}
